INSERT INTO feature VALUES('ascription','calculus','Type ascription','call-by-push-value','implemented','ordinary',NULL,'A term ascribed a type synthesises it and checks the term against it: `(e : T)` ascribes the value it encloses wherever a value is read, an application''s head included, a computation is ascribed by `let d : T = e`, which binds at a written type, a name or a tuple pattern alike, and the kernel replays each stated type where it synthesises.','core-term core-checker kernel-core surface-lowering','corpus/surface/typed-bind.gandr corpus/surface/typed-bind-parameters.gandr corpus/pathological/basics/ill-typed-ascription.gandr corpus/model/basics/annotations.gandr corpus/pathological/basics/annotations.gandr','corpus/surface/typed-bind.gandr',NULL);
